import{_ as u,a0 as l,w as o,s as a,I as n,x as p,a1 as r,A as s,ao as d}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const f=JSON.parse('{"title":"一步步安裝Ubuntu 13.10服務版 | LCTT x X-CMD","titleTemplate":false,"description":"一步步安裝Ubuntu 13.10服務版 | LCTT (201311) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"一步步安裝Ubuntu 13.10服務版 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"一步步安裝Ubuntu 13.10服務版 | LCTT (201311) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201311/Install Ubuntu 13.10 Server Step by Step","title":"一步步安裝Ubuntu 13.10服務版","tag":"201311","desc":""},"relativePath":"201311/Install Ubuntu 13.10 Server Step by Step.md","filePath":"[post].md"}'),i={name:"201311/Install Ubuntu 13.10 Server Step by Step.md"};function g(m,t,c,S,b,v){const e=l("Link");return o(),a("div",null,[t[14]||(t[14]=n("h1",{id:"一步步安裝ubuntu-13-10服務版",tabindex:"-1"},[p("一步步安裝Ubuntu 13.10服務版 "),n("a",{class:"header-anchor",href:"#一步步安裝ubuntu-13-10服務版","aria-label":"Permalink to “一步步安裝Ubuntu 13.10服務版”"},"​")],-1)),t[15]||(t[15]=n("p",null,[p("如你所見，這是一篇關於"),n("strong",null,"Ubuntu 13.10服務版的安裝"),p("的指南。")],-1)),n("p",null,[t[1]||(t[1]=p("下載最新的版本",-1)),n("strong",null,[r(e,{href:"http://releases.ubuntu.com/saucy/"},{default:s(()=>[...t[0]||(t[0]=[p("Ubuntu 13.10 服務版",-1)])]),_:1})]),t[2]||(t[2]=p("，然後用刻錄好的Ubuntu 13.10服務版光盤引導你的服務器，你將會看到類似下面的顯示。",-1))]),t[16]||(t[16]=d('<p>首先選擇您的語言：（建議使用英文）</p><p><img src="http://180016988.r.cdn77.net/wp-content/uploads/2013/10/Server1.png" alt=""></p><p>點擊安裝Ubuntu服務版：</p><p><img src="http://180016988.r.cdn77.net/wp-content/uploads/2013/10/Server2.png" alt=""></p><p>選擇安裝過程中所使用的語言：</p><p><img src="http://180016988.r.cdn77.net/wp-content/uploads/2013/10/Server3.png" alt=""></p><p>選擇你的國家（譯註：用於決定時區，請選擇中國，使用+8時區）：</p><p><img src="http://180016988.r.cdn77.net/wp-content/uploads/2013/10/Server4.png" alt=""></p><p>配置區域設置：（譯註：對於服務器版本，我們建議一律採用英文的locale—— en_US.UTF-8，當然，你可以增加中文字體包，但是保持服務器環境是英文環境，有助於減少出現奇怪問題的幾率。）</p><p><img src="http://180016988.r.cdn77.net/wp-content/uploads/2013/10/Server5.png" alt=""></p><p>檢測鍵盤佈局（譯註：一般不必檢測）：</p><p><img src="http://180016988.r.cdn77.net/wp-content/uploads/2013/10/Server6.png" alt=""></p><p>選擇鍵盤佈局（譯註：如下圖的英文即可）：</p><p><img src="http://180016988.r.cdn77.net/wp-content/uploads/2013/10/Server7.png" alt=""></p><p><img src="http://180016988.r.cdn77.net/wp-content/uploads/2013/10/Server8.png" alt=""></p><p>自動檢測網絡設置：</p><p><img src="http://180016988.r.cdn77.net/wp-content/uploads/2013/10/Server9.png" alt=""></p><p>輸入你的服務器主機名（譯註：作為服務器，尤其是運行在互聯網上的，一般都輸入包括域名在內的完全限定主機名。）：</p><p><img src="http://180016988.r.cdn77.net/wp-content/uploads/2013/10/Server10.png" alt=""></p><p>輸入用户名以創建一個非特權用户（譯註：操作服務器要習慣使用普通用户操作，<strong>僅僅</strong>在必要使用使用sudo來使用root權限。）：</p><p><img src="http://180016988.r.cdn77.net/wp-content/uploads/2013/10/Server11.png" alt=""></p><p>設置用户的密碼：</p><p><img src="http://180016988.r.cdn77.net/wp-content/uploads/2013/10/Server12.png" alt=""></p><p>如果你想加密用户主目錄，選擇Yes，否則選擇No（譯註：這點無所謂。）：</p><p><img src="http://180016988.r.cdn77.net/wp-content/uploads/2013/10/Server13.png" alt=""></p><p>選擇分區方案（譯註：如果你有特定需求，可以採用manual分區方式，沒有經驗的用户可以使用預設的Guied分區模式。關於分區，是一個值得系統管理員仔細研究的課題，建議搜索更多深入的文章來看看，或者在此進行討論）：</p><p><img src="http://180016988.r.cdn77.net/wp-content/uploads/2013/10/Server14.png" alt=""></p><p>開始安裝：</p><p><img src="http://180016988.r.cdn77.net/wp-content/uploads/2013/10/Server15.png" alt=""></p><p>如果在你的網絡上有代理服務，輸入代理服務的IP地址（譯註：絕大多數的服務器都是直接接入互聯網，並有公網IP的，所以不會使用代理服務器的。）：</p><p><img src="http://180016988.r.cdn77.net/wp-content/uploads/2013/10/Server16.png" alt=""></p><p>選擇安全更新的安裝方式，然後回車（譯註：我不同意原文的選擇。對於服務器，不建議採用自動更新，因為服務器的第一要務是穩定；在出現必要的安全更新補丁時，系統管理員要評估並測試是否應該安裝，是否會對現有應用造成影響，如果可以通過其他方式，如防火牆來消除安全隱患，那麼一動不如一靜，不安裝任何補丁和更新為好。）：</p><p><img src="http://180016988.r.cdn77.net/wp-content/uploads/2013/10/Server17.png" alt=""></p><p>選擇要安裝的軟件（譯註：僅僅選擇你的服務器所必須的，暫時不用的，最好不要選擇。將來需要增加或許修改時，你還有足夠的時間去改變。）：</p><p><img src="http://180016988.r.cdn77.net/wp-content/uploads/2013/10/Server18.png" alt=""></p><p>點擊Yes安裝Grub引導裝載程序（譯註：這裏一般沒有別的選擇，肯定是安裝Grub，除非你有特別的理由給服務器安裝其他的引導器。）：</p><p><img src="http://180016988.r.cdn77.net/wp-content/uploads/2013/10/Server20.png" alt=""></p><p>安裝完成以後，選擇continue重啓服務器即可：</p><p><img src="http://180016988.r.cdn77.net/wp-content/uploads/2013/10/Server21.png" alt=""></p><p>登入Ubuntu服務器：</p><p><img src="http://180016988.r.cdn77.net/wp-content/uploads/2013/10/Server22.png" alt=""></p><p>輸入用户名和密碼登錄（譯註：如你所見，服務器版默認是沒有圖形界面的，一般而言，除非你有一個必須圖形界面運行的程序，否則不要安裝圖形界面。不安裝圖形界面的主要原因是，減少不必要的包和服務，每多一個服務就會多帶來一份安全威脅的可能性，當然，也會消耗一點內存和處理能力。你現在可以在登錄後輸入ps或者pstree看看已經運行的服務有多少。）：</p><p><img src="http://180016988.r.cdn77.net/wp-content/uploads/2013/10/Server23.png" alt=""></p><p><img src="http://180016988.r.cdn77.net/wp-content/uploads/2013/10/Server24.png" alt=""></p><p>這就是這次的指南。現在你的Ubuntu 13.10 服務版已經啓動運行了。</p><hr>',46)),n("p",null,[t[4]||(t[4]=p("via: ",-1)),r(e,{href:"http://www.unixmen.com/install-ubuntu-server-13-10-step-step/"},{default:s(()=>[...t[3]||(t[3]=[p("http://www.unixmen.com/install-ubuntu-server-13-10-step-step/",-1)])]),_:1})]),n("p",null,[t[7]||(t[7]=p("譯者：",-1)),r(e,{href:"https://github.com/Luoxcat"},{default:s(()=>[...t[5]||(t[5]=[p("Luoxcat",-1)])]),_:1}),t[8]||(t[8]=p(" 校對：",-1)),r(e,{href:"https://github.com/wxy"},{default:s(()=>[...t[6]||(t[6]=[p("wxy",-1)])]),_:1})]),n("p",null,[t[11]||(t[11]=p("本文由 ",-1)),r(e,{href:"https://github.com/LCTT/TranslateProject"},{default:s(()=>[...t[9]||(t[9]=[p("LCTT",-1)])]),_:1}),t[12]||(t[12]=p(" 原創翻譯，",-1)),r(e,{href:"http://linux.cn/"},{default:s(()=>[...t[10]||(t[10]=[p("Linux中國",-1)])]),_:1}),t[13]||(t[13]=p(" 榮譽推出",-1))])])}const U=u(i,[["render",g]]);export{f as __pageData,U as default};
